//! Decision traces: what was recalled, which candidates were scored, and why
//! one was chosen. Traces record computation only, never invented inner speech.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

use crate::world::RegulatoryState;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CandidateSource {
    /// A taught, corrected, or reinforced prompt/response association.
    Association,
    /// Text recalled from a memory or ingested document.
    Recall,
    /// Text generated by the language model.
    Generated,
    /// A question back to the owner.
    Question,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Recalled {
    pub source: String,
    pub score: f64,
    pub excerpt: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Candidate {
    pub text: String,
    pub source: CandidateSource,
    pub score: f64,
    /// Named score components (similarity, weight, fluency, ...).
    pub components: BTreeMap<String, f64>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Decision {
    Reply,
    Ask,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ThoughtTrace {
    pub engine: String,
    pub input_terms: Vec<String>,
    pub unknown_terms: Vec<String>,
    pub recalled: Vec<Recalled>,
    pub candidates: Vec<Candidate>,
    /// Index into `candidates` of the chosen candidate, if any.
    pub chosen: Option<usize>,
    pub decision: Decision,
    pub confidence: f64,
    /// Threshold the best candidate had to beat (level-adjusted).
    pub threshold: f64,
    /// Exploration rate in effect for this turn (self-regulated).
    pub exploration: f64,
    pub explored: bool,
    pub levels: RegulatoryState,
    pub notes: Vec<String>,
}
